package com.cpf.starter.jms;import com.cpf.starter.base.*;import com.cpf.starter.messaging.reliability.CpfNamedBrokerClient;import jakarta.jms.ConnectionFactory;import java.util.Map;import org.springframework.boot.autoconfigure.AutoConfiguration;import org.springframework.boot.autoconfigure.condition.ConditionalOnBean;import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;import org.springframework.boot.context.properties.EnableConfigurationProperties;import org.springframework.context.annotation.Bean;import org.springframework.jms.config.DefaultJmsListenerContainerFactory;import org.springframework.jms.core.JmsTemplate;
@AutoConfiguration @EnableConfigurationProperties(CpfJmsProperties.class) @ConditionalOnProperty(prefix="cpf.messaging.jms",name="enabled",havingValue="true")
public class CpfJmsAutoConfiguration {@Bean JmsTemplate cpfJmsTemplate(ConnectionFactory cf,CpfJmsProperties p){p.validate();JmsTemplate t=new JmsTemplate(cf);t.setPubSubDomain(p.isPubSubDomain());t.setSessionTransacted(p.isSessionTransacted());t.setSessionAcknowledgeMode(p.getAcknowledgementMode());return t;}@Bean DefaultJmsListenerContainerFactory cpfJmsListenerContainerFactory(ConnectionFactory cf,CpfJmsProperties p){var f=new DefaultJmsListenerContainerFactory();f.setConnectionFactory(cf);f.setPubSubDomain(p.isPubSubDomain());f.setSessionTransacted(p.isSessionTransacted());f.setSessionAcknowledgeMode(p.getAcknowledgementMode());return f;}@Bean CpfJmsBrokerClient cpfJmsBrokerClient(JmsTemplate t,CpfJmsProperties p){return new CpfJmsBrokerClient(t,p);}@Bean CpfNamedBrokerClient cpfJmsNamedBrokerClient(CpfJmsBrokerClient c,CpfJmsProperties p,CpfCapabilityBindingRegistry r){r.register(new CpfCapabilityBinding("messaging",p.getBindingName(),"jms",p.isDefaultBinding(),Map.of("destination",p.getDestination())));return new CpfNamedBrokerClient(p.getBindingName(),"jms",p.isDefaultBinding(),c);}}
